import {readFileSync,existsSync} from 'node:fs';import {dirname,resolve,join} from 'node:path';import {fileURLToPath} from 'node:url';import {execFileSync} from 'node:child_process';import {createHash} from 'node:crypto';import assert from 'node:assert/strict';
const dir=dirname(fileURLToPath(import.meta.url)),root=resolve(dir,'../../../..');const sha=b=>createHash('sha256').update(b).digest('hex');const json=f=>JSON.parse(readFileSync(join(dir,f),'utf8'));
for(const line of readFileSync(join(dir,'SHA256SUMS'),'utf8').trim().split('\n')){const m=/^([a-f0-9]{64})  (.+)$/.exec(line);assert.ok(m);assert.equal(sha(readFileSync(join(dir,m[2]))),m[1],m[2]);}
const manifest=json('source-manifest.json'),report=json('report.json'),commands=json('commands.json');assert.equal(manifest.candidate,report.sourceCandidate);assert.equal(commands.candidate,manifest.candidate);assert.ok(commands.records.every(r=>r.exitCode===0&&r.status==='finished'));
for(const f of manifest.files){assert.equal(sha(execFileSync('git',['show',manifest.candidate+':'+f.path],{cwd:root,windowsHide:true,maxBuffer:30000000})),f.sha256,f.path);if(process.argv.includes('--working-tree'))assert.equal(sha(readFileSync(join(root,f.path))),f.sha256,f.path);}
for(const file of ['task-tests.json','chat-tests.json']){const r=json(file);assert.equal(r.numFailedTests,0);assert.equal(r.numPassedTests,r.numTotalTests);}
assert.equal(json('electron.json').stats.expected,2);assert.equal(json('electron.json').stats.unexpected,0);assert.equal(json('electron-visual.json').stats.expected,1);assert.equal(json('electron-visual.json').stats.unexpected,0);assert.equal(json('runtime-build.json').exitCode,0);
const ui=json('task-ui-readback.json');assert.equal(ui.hiddenPersists,true);assert.equal(ui.hidePreservesClaim,true);assert.deepEqual(ui.languages,['en','zh','ja','ru']);for(const file of json('visual-review.json').images)assert.ok(existsSync(join(dir,file)));
console.log(JSON.stringify({passed:true,candidate:manifest.candidate,sourceFiles:manifest.files.length,taskTests:report.taskTests,chatTests:report.chatTests,electron:2,visualReplay:1,locales:4}));
